using System.IO;
using System.Text;
using RDPManager.Models;

namespace RDPManager.Services;

/// <summary>Creates connections from existing .rdp files.</summary>
public static class RdpFileImporter
{
    // Settings that map to Connection properties or are always generated by RdpLauncher.
    private static readonly HashSet<string> Generated = new(StringComparer.OrdinalIgnoreCase)
    {
        "full address:s", "username:s", "screen mode id:i", "use multimon:i", "selectedmonitors:s",
        "desktopwidth:i", "desktopheight:i", "redirectclipboard:i", "redirectprinters:i", "drivestoredirect:s",
        "audiomode:i", "gatewayhostname:s", "gatewayusagemethod:i", "gatewayprofileusagemethod:i",
        "gatewaycredentialssource:i", "promptcredentialonce:i", "administrative session:i",
        "prompt for credentials:i", "dynamic resolution:i", "session bpp:i", "connection type:i",
        "networkautodetect:i", "bandwidthautodetect:i", "displayconnectionbar:i", "pinconnectionbar:i",
        "autoreconnection enabled:i", "authentication level:i", "enablecredsspsupport:i",
    };

    public static Connection Import(string path)
    {
        var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var order = new List<string>();
        foreach (var line in ReadLines(path))
        {
            var parts = line.Split(':', 3);
            if (parts.Length != 3)
                continue;
            var key = $"{parts[0].Trim()}:{parts[1].Trim()}";
            if (!values.ContainsKey(key))
                order.Add(key);
            values[key] = parts[2].Trim();
        }

        string Get(string key, string fallback = "") => values.TryGetValue(key, out var v) ? v : fallback;

        var c = new Connection { Name = Path.GetFileNameWithoutExtension(path) };
        var address = Get("full address:s");
        var colon = address.LastIndexOf(':');
        if (colon > 0 && !address.EndsWith(']') && int.TryParse(address[(colon + 1)..], out var port))
        {
            c.Host = address[..colon];
            c.Port = port;
        }
        else
        {
            c.Host = address;
        }

        c.Username = Get("username:s");
        if (c.Username.Length > 0)
            c.CredentialMode = CredentialMode.Username;
        c.FullScreen = Get("screen mode id:i", "2") == "2";
        c.UseMultimon = Get("use multimon:i") == "1";
        c.SelectedMonitors = Get("selectedmonitors:s");
        if (int.TryParse(Get("desktopwidth:i"), out var w)) c.Width = w;
        if (int.TryParse(Get("desktopheight:i"), out var h)) c.Height = h;
        c.RedirectClipboard = Get("redirectclipboard:i", "1") == "1";
        c.RedirectPrinters = Get("redirectprinters:i") == "1";
        c.RedirectDrives = Get("drivestoredirect:s").Length > 0;
        if (int.TryParse(Get("audiomode:i"), out var audio) && Enum.IsDefined(typeof(AudioMode), audio))
            c.AudioMode = (AudioMode)audio;
        if (Get("gatewayusagemethod:i") is "1" or "2")
            c.GatewayHost = Get("gatewayhostname:s");
        c.AdminSession = Get("administrative session:i") == "1";

        c.ExtraRdpSettings = string.Join("\r\n",
            order.Where(k => !Generated.Contains(k)).Select(k => $"{k}:{values[k]}"));
        return c;
    }

    private static IEnumerable<string> ReadLines(string path)
    {
        // mstsc writes UTF-16 LE with BOM; StreamReader detects the BOM, otherwise falls back to UTF-8.
        using var reader = new StreamReader(path, Encoding.UTF8, detectEncodingFromByteOrderMarks: true);
        while (reader.ReadLine() is { } line)
            yield return line;
    }
}
